// ─────────────────────────────────────────────────────────────
//  게임 밸런스/조작감 숫자는 모두 여기에 모아둔다.
//  "무기가 너무 가볍다", "적이 너무 세다" 같은 느낌은
//  코드를 뜯지 말고 이 파일의 숫자부터 바꿔보면 된다.
//  단위: 미터(m), 킬로그램(kg), 초(s), 뉴턴(N)
//  [사장님 M/D] = 사장님이 이 값을 정함
//  [사장님 M/D · 값 감독] = 기능은 사장님이 시킴 · 숫자는 감독
//  표시 없음 또는 [확인 전] = 감독 값(사장님 확인 전)
// ─────────────────────────────────────────────────────────────

// ── 표준 시간: 게임은 템포 1.1 로 빨리 돈다 — 사람이 느끼는 규칙 시간 · 빠르기 문턱은 실제 값으로 적고 realS · realV · realRate 로 바꿈(물리 · 서보 · 걸음 기계 · 동작 대본 · 잰 값은 안 감쌈) [사장님 10/25]
export const TIME = { tempo: 1.1, k: 1.1 }; // k = 실제 초 → 게임 초 배율 · 템포 1.1 (사장님 10/10 05:1x '기본 템포 1.1로') — main.js TEMPO 가 이 값을 쓴다
/** 실제 초 → 게임 초 (규칙 시간: 창 · 굳음 · 기다림 · 반응 · 걸쇠 · 무장 · 효과 시간) */
export const realS = (s) => s * TIME.k;
/** 실제 m/s → 게임 m/s (규칙 빠르기: 걷기 목표 · 달려듦 문턱처럼 사람이 m/s 로 정한 수) */
export const realV = (v) => v / TIME.k;
/** 실제 초당 몫 → 게임 초당 몫 (기력 회복 초당 15 · 출혈 초당 몫처럼 '초당' 규칙 수) */
export const realRate = (r) => r / TIME.k;

export const PHYSICS = {
  gravity: -9.81,
  timestep: 1 / 120, // 물리 한 스텝 길이. 작을수록 안정적이지만 무겁다.
  maxStepsPerFrame: 6, // 프레임이 밀렸을 때 따라잡기 위한 최대 스텝 수
};

// 기력(스태미너) — 계산 src/stamina.js(사람 · AI 같은 장부) · 막대 src/stamina_hud.js · 100 … 0 아래 지침 … −35 아래 심한 지침 … −70 탈진 · 설계 docs/design/stamina_2026-10-15.md [사장님 10/17]
export const STAMINA = {
  // 단계 문턱: 0 아래 지침 · severeAt 아래 심한 지침 · floor 탈진 [사장님 10/17] · stageBack = 한 단계 위로 돌아오려면 문턱보다 더 채울 몫 [확인 전]
  max: 100, floor: -70, severeAt: -35, stageBack: 15,
  // 지친 이동 배율(지침 · 심한 지침) — 공격 쪽은 아래 tempo* 가 첫 실제 접촉까지 시간을 1.25 · 1.667 배로 맞춤 [사장님 10/17]
  moveTired: 0.7, moveSevere: 0.4,
  // 기력 비용: 베기 12 · 찌르기 10 · 막아 받기 3 (× 무게) · 비기 35 · 첫 걸음 박차기 12 (무게 없음) · 권총 한 발 2 × 무게 — thrustCost [사장님 10/24] · secretCost [사장님 10/15] · shotCost [사장님 11/21 권고대로] · cutCost · blockCost · pushCost [확인 전]
  cutCost: 12, thrustCost: 10, blockCost: 3, secretCost: 35, pushCost: 12, shotCost: 2,
  clinchPerSecond: realRate(10), // 붙어 밀고 버티는 동안(밀치기 누르기 + 팔·칼 닿음) 두 몸 각각 초당 10 · 회복 멈춤(샛별 저장소 ba14a6f8) [사장님 11/21 권고대로]
  // 사람 긋기 청구(샛별 저장소 f933bc07): 끊김 0.12 s 넘으면 새 긋기(설계안은 고유 동작의 onsetQuiet 0.06) · 손이 0.06 m 넘게 움직여야 · 겨눔 가운데 0.22 m 를 가르는 긋기는 바로 확정 — strokeQuiet [사장님 11/21 권고대로] · strokeTravel · strokeCenter [확인 전]
  strokeQuiet: realS(0.12), strokeTravel: 0.06, strokeCenter: 0.22,
  // 사람 손가락 긋기를 베기로 청구하는 손 목표 이동 바닥(패드 m) — 가벼운 손끝 · 미끄러짐은 청구 안 함 · 칼이 닿으면 짧아도 청구 · AI · 시뮬 몸은 strokeTravel [사장님 10/31]
  humanStrokeMin: 0.15,
  weaponReferenceMass: 1.6, // 무게 = √(처음 쥔 칼 질량 ÷ 1.6 kg) 0.75 ~ 1.5 — 칼이 부러져도 처음 질량(사장님 결정)
  // 걷기 기력: 골반 0.6 m 마다 보통 4 · 동방 2 · 일본 6 · 뒷걸음은 × 1.5 [사장님 10/31] · 한 스텝 거리 상한 3 m/s(튐 막기 — maxWalkSpeed 는 감독 값)
  stepDistance: 0.6, stepCosts: { default: 4, chinese: 2, japanese: 6 }, backStepCostMul: 1.5, maxWalkSpeed: 3,
  // 회복: 0.6 s 동안 공격 · 막아 받기 · 박차기 · 비기 · 클린치를 안 쓰면 AI 초당 15 · 시뮬 대본 몸 21 · 막기 유지 중엔 멈춤 [21 은 확인 전 — 사람 입력 몸 25 는 사장님 10/29]
  recoverPerSecond: realRate(15), playerRecoverPerSecond: realRate(21), recoverDelay: realS(0.6), // 표준 시간: 실제 초당 · 실제 초 (10/25)
  // 사람 입력이 모는 몸만 초당 회복 25 (AI 15 · 시뮬 대본 몸 21 그대로) [사장님 10/29]
  humanRecoverPerSecond: realRate(25), // [사장님 10/29 17:5x 결정]
  // 탈진: 바닥(−70)에서 이동 · 공격 불가 · 자연 회복 빠르기로 차서 −35 에서 풀림 · tempoPower* 공격 중 지친 팔 · 손목 힘 · tempoRate* 베기 · 비기 시계 · tempoThrust* 찌르기 · tempoPommel* 손잡이 찍기 — 탈진 [사장님 10/18] · tempo* 값은 줄마다
  tempoPowerTired: 0.64, tempoPowerSevere: 0.36, // [사장님 11/21 권고대로]
  tempoRateTired: 0.8, tempoRateSevere: 0.6, // [사장님 10/17 · 값 감독]
  tempoThrustTired: 0.75, tempoThrustSevere: 0.55, tempoHeavyMass: 2.5, // tempoThrust* [사장님 11/21 권고대로] · tempoHeavyMass [사장님 10/17 · 값 감독]
  tempoPommelTired: 0.72, tempoPommelSevere: 0.50, // [사장님 10/17 · 값 감독]
  tiredPower: 0.64, severePower: 0.36, // 지침·심한 지침의 팔·손목 힘 배율 — 막는 동안만(공격 중엔 tempoPower* — 같은 값) [사장님 11/21 권고대로 — 전 0.49 · 0.25 = 10/17 전 배율 0.7 · 0.5 의 제곱이 남은 시작값 · 감사 N-001 ⑤]
  aiRestAt: 20, aiAggressiveRestAt: -10, aiResumeAt: 35, // AI: 20 아래(공격적 기질 −10 아래) 새 공격 멈추고 물러남 · 35 에서 다시(되돌림 35 는 샛별 저장소 값) — aiRestAt · aiResumeAt [사장님 11/21 권고대로] · aiAggressiveRestAt [확인 전]
};
// 무기 특수 능력 값(능력은 weapons.js 무기 스펙 · 값만 여기 · 늘 켜짐) — aweStart: 티소나 '위세' 상대가 그 판을 최대 기력 − 15 로 시작 [사장님 10/24 · 값 감독]
export const WEAPON_ABILITY = { aweStart: 15 };
// 달타냥 '총사의 결투': 칼 주인이 한손검을 쥔 상대를 치면 그 칼 공격력(판정 에너지 배율) × duelOneHand (1 = 끔 · 물리는 그대로) [사장님 10/25]
WEAPON_ABILITY.duelOneHand = 1.15; // 사장님 10/25 결정
// 드루이드의 채찍 무릎 꿇리기: 사람 채찍 한 획의 첫 맞음에서 확률 p(× 맞는 쪽 버티기)로 kneel 초 꿇림 — 곁눈 베기 무릎 꺾기와 같은 틀 [사장님 10/23 · 값 확인 전]
export const WHIP_KNEEL = { p: 0.5, kneel: realS(0.6) }; // kneel 0.4 → 0.6 [사장님 11/14 결정 '채찍도 같이 0.6초로 해' — 확인표 3861]

// 바닥 면적 2배: 길이는 √2배. 인물·무기·시작 간격은 확대하지 않는다.
export const ARENA_SCALE = Math.SQRT2;
export const ARENA = {
  radius: 6.5 * ARENA_SCALE, // 원형 경기장 반지름 (대리석 경계 테두리 위치)
  startGap: 5.6, // 시작할 때 두 검투사 사이 거리. 사장님 9/30 "멀리 떨어트려 맵을 보게"(4.2 → 7.0) → 09:10 "너무 떨어져 있어, 조금만 붙이자, 그래도 초기보다는 멀게"(→ 5.6, 롱소드 닿는 거리 밖 3.6 m)
  aiWall: 1.9, // AI 울타리 몰림 띠: 반지름 − aiWall(m) 밖이면 옆으로 빠져 가운데로 [사장님 11/19]
  startHold: 2.0, // 판 시작 뒤 이 시간 동안 두 몸 발만 묶음(팔 · 칼 자유) — 시뮬 · 도구 판은 게임 초 · 브라우저는 실제 2.0 s [사장님 값]
};

// 동시 대전 2:2 · 2:1 (사장님 10/29 14:2x 생사전 — docs/strike/team_fight_2026-10-29.md · src/team.js · src/match.js). 1:1 은 이 값을 읽지 않는다
export const TEAM_FIGHT = {
  mateGap: 1.6, // 한 편 둘이 시작할 때 옆(z)으로 벌린 거리 (m, 골반 사이). 편 사이는 ARENA.startGap 그대로 · 사장님 확인 전 (확인표 2860)
  // 상대 고르기 (src/targeting.js — 2단계 10/29). 점수 = 가슴 수평 거리(m) + 아래 더함 · 뺌 — 낮을수록 고름 · 난수 없음 · 모두 사장님 확인 전 (확인표 2864 ~ 2869)
  target: {
    downNear: 3.0, // 쓰러진(서 있지 않은) 상대: 다른 상대가 이 거리(m) 안에 서 있으면 … (2864)
    downAdd: 1.0, //  … 점수 + 1.0 (서 있는 상대 먼저) (2864)
    allyAdd: 0.8, // 내 편이 이미 겨눈 상대 하나마다 + 0.8 (나눠 맡기) (2865)
    attackSub: 1.5, // 나를 겨눠 제 칼끝 거리(reach) 안에서 치고 있는 상대 − 1.5 (2866)
    margin: 0.8, // 바꾸려면 새 상대가 이만큼(m) 더 낮아야 (2867)
    hold: realS(1.2), // … 그리고 이 시간 동안 내리 낮아야 (실제 초 — 시간 사다리 1.2 · 나를 치는 상대는 기다림 없이) (2867)
    prefAdd: 1.0, // 인물별 2:2 겨눔 취향 덧셈 크기 (weakest · strongest · allyAttacker — 갈고리만, 아직 쓰는 인물 없음) (2868)
    attackHold: realS(0.2), // '나를 침' 바꿈: 그 상대가 나를 이만큼(실제 초 — 시간 사다리 0.2) 내리 치고 있어야 (0 = 곧장 — 2단계) — 사장님 10/29 20:3x '2:1에서 혼자인 쪽이 몸을 돌리는 시간 공격해 오는 쪽 0.2초 이상으로' (2877)
    // 사람 몸(AI 조종 없는 몸)이 보는 적: 가장 가까운 적 · 바꾸려면 margin m 더 가까운 채 hold 초 [사장님 11/21 · 값 확인 전]
    human: { allyAdd: 0, margin: 0.5, hold: realS(0.4) },
  },
  // 상대 둘 (AI — ai.js teamFeet): 간 보기 · 물러남 동안 다른 상대가 range 안에서 지금 상대와 angle 넘게 벌어져 있으면 그 반대 옆으로 비켜 둘을 한 줄로 (2870)
  flank: { range: 3.5, angle: 70, side: 0.6 }, // m · 도(°) · 스틱 옆 몫
  block: 0.6, // 지금 상대가 아닌 상대 몸이 내 붙은 거리(M.clinch) 안: 그쪽으로는 스틱을 못 밀고, 가까울수록 이 몫(스틱)까지 밀려남 (2871)
  mateSep: { dist: 0.9, k: 0.8 }, // 같은 편 사이 (가슴 수평 m): 가까우면 서로 비킴 — 가까울수록 k 몫(스틱)까지 · 베는 동안은 안 비킴 (2872)
  // 3단계 (10/29 — main.js 동시 대전 판): 카메라 물러남 · 죽은 몸 쉬게 하기 — 사장님 확인 전 (확인표 2875 · 2876)
  cam: { radius: 7, fit: 0.85, minDepth: 2.4, max: 3.0, upK: 0.45, tau: realS(0.6), fovAdd: 6 }, // 보는 몸에서 radius m 안의 산 싸움꾼이 모두 화면에 들게 뒤로(≤ max m): 화면 가로 반폭의 fit 몫 안 · 카메라 앞 깊이 minDepth m 넘게 · 위로 그 × upK · 시간 상수 tau (2875)
  //  fovAdd 셋 이상 판(동시 대전) 카메라 세로 시야각 + 이만큼(°) — 1:1 55° → 61° (11/21 사장님 '시야를 조금 넓히고' · 물러남 셈은 1:1 시야각 그대로라 넓힌 몫이 고스란히 더 보임) [사장님 확인 전]
  deadSettle: { t: realS(1.5), v: 0.05 }, // 죽은 지 t 넘게 · 몸 부위가 모두 v m/s 밑이면 그 몸은 스텝 · 조종 · 칼 잔상 · 바람 소리를 쉼 (셋 이상 판만 — 2876)
  // 적 화면 색 = 피 색의 OKLCH 채도 × foeChromaK [사장님 10/30 · 0.7 확인 전]
  hudColor: { foeChromaK: 0.7 },
  // 체력 칸: cells 칸 수 · tones [문턱, 색] (80 · 50 · 20 %) [사장님 11/18] · bleedAt 점멸 출혈 문턱 · h 칸 높이 · gap 틈(px) [사장님 11/18 · 값 감독]
  hpStrip: { cells: 10, tones: [[0.8, 'green'], [0.5, 'yellow'], [0.2, 'orange']], low: 'red', bleedAt: 0.002, h: 3, gap: 2 },
  // 2:1 숙련도 몫(셋 이상 판의 AI 만): sk = (p − prof[0]) ÷ (prof[1] − prof[0]) 를 0 ~ 1 로 — 줄 세우기 · 위협 읽기 [사장님 11/21 권고대로]
  lever: {
    prof: [2, 6], // 숙련도 2 이하 = 0 (똑똑해지지 않음) · 6 = 1
    lineUp: { on: true, range: 4.5, side: 1.0, full: 0.8, backFrom: 95, back: 1.0 }, // 줄 세우기: 다른 상대를 지금 상대 뒤로 (옆 몫 side × sk × min(1, 벌어진 각 ÷ full rad)) · 집게(각 > backFrom°)면 물러남 back × sk
    evade: { on: true, gap: 0.8, k: 1.2 }, // 모든 상대의 위협 읽기: 지금 상대가 아닌 상대가 나를 치러 칼끝 거리 + gap 안이면 그 몸에서 k × sk 만큼 비킴
  },
};

// 무리 싸움 판단(셋 이상 판의 AI 만 · src/team_sense.js · 설계 docs/design/team_sense_2026-11-18.md) — 값은 작업자 안 [사장님 11/18 권고대로]
export const TEAM_SENSE = {
  frame: 0.05, // 판 사본 한 장 간격 (게임 초 — 표본 박자 · 사람이 느끼는 규칙 시간이 아님)
  // 층마다 눈 (§3-0 · §4): 앞 fov° 안만 보임 · lag(실제 초) 지난 장을 읽음 · 지금 겨눈 상대는 늘 보임. 6 = 사방 [사장님 11/18 결정 1 '발소리로 듣는 셈']
  eye: { base: { fov: 120, lag: realS(0.6) }, mid: { fov: 200, lag: realS(0.4) }, top: { fov: 360, lag: realS(0.2), ahead: realS(1.2) } },
  engage: 0.5, // 붙음 = 겨눈 상대가 제 칼끝 + 이 m 안 (재기 도구 team_sense.mjs 의 '닿는 거리'와 같음)
  // 칼길 비우기 (§3-1 — 바탕): 나 → 상대 줄에서 w m 안에 선 동료 · 그 동료가 내 칼끝 + sweep m 안 · 앞 ± fan° 면 새 공격을 hold(실제 초) 동안 미룸 · 줄에서 비키는 스틱 몫 k
  lane: { w: 0.45, sweep: 0.3, fan: 45, hold: realS(0.2), k: 0.6 },
  // 협공 자리 (§3-3): 목표 각 θ*(°) — 바탕 base(나란히 · 동료 뒤 줄만 피함) · 가운데 base → mid(몫 k) · 위 top. 못 미친 각이 tol° 넘으면 상대를 축으로 도는 스틱 몫 k ·
  //  동료가 그 상대에 '가까움' = 동료 칼끝 + engage + near m 안
  pincer: { base: 60, mid: 120, top: 160, tol: 15, k: 0.6, kTop: 1.0, near: 0.6 }, // kTop: 6 의 도는 스틱 몫
  // 엄호 (§3-6 — 바탕): 넘어짐 · 무릎 · 피 blood 밑 동료를 겨눈 적 − sub (상대 고르기 점수) · 그 바꿈은 hold(실제 초) 기다림 (예전 1.2 s 대신) ·
  //  가운데 · 위: 그 적과 동료 사이로 끼어드는 스틱 몫 k × 층 몫
  cover: { sub: 1.5, blood: 0.75, hold: realS(0.4), k: 0.6 },
  // 노릴 상대 (§3-2 — 가운데 · 위, × 층 몫 k): 내 동료와 붙어 내게 옆 · 등을 보인 적 − side · 다친 적 − wound × 다침(combat.js woundDegree) · 지친 적 − tired ·
  //  피 focus 밑 적은 나눠 맡기 덧셈(TEAM_FIGHT.target.allyAdd)을 거둠(몰아침 §3-7) — 지금 상대가 나를 붙잡고 있으면(나를 겨눠 붙음) 이 덧셈은 없음
  opp: { side: 1.0, wound: 0.6, tired: 0.4, focus: 0.6 },
  // 기습 (§3-4): 겨눈 상대가 내 동료와 붙었고 내가 그 앞(± front°) 밖이면 빈틈 점수 + mid × 층 몫 ('ambush' — ai.js opportunity) ·
  //  6: 그 상대가 동료에게 칼을 내는 순간 + top · 내지 않는 동안 wait(실제 초)까지 빈틈 점수 − hold(기다림) · 지나면 + mid
  //  기습 자리: 가운데 · 위는 그 상대가 남과 붙은 동안 내 칼끝 + near m 에 섬 (그 상대의 칼끝 밖이 아니라 — ai.js holdDist)
  ambush: { front: 60, mid: 0.6, top: 1.2, wait: realS(1.2), hold: 0.3, near: 0.3 },
  // 틈 베기 (§3-4 · §3-7 — 6): 남과 붙어 내게 옆 · 등을 보인 적이 내 칼끝 + near m 안이고 지금 상대가 나를 치는 중이 아니면 붙잡혀 있어도 − sub · hold(실제 초) 만에 바꿈 · 기습 빈틈은 기다림 없이 + ambush.top
  shot: { near: 0.3, sub: 1.0, hold: realS(0.2) },
  // 2:2 → 2:1 (§3-7 — 6): 내 동료와 붙은 적을 옆 · 등을 안 보여도 − opp.side · 동료가 지고 있으면(서 있지 않음 · 내다본 피가 그 적보다 margin 넘게 낮음) − sub 더
  two: { sub: 0.8, margin: 0.15 },
  // 방패 (§3-5 — 6): 지금 상대 뒤로 남과 붙지 않은 다른 적이 한 줄(나에게서 angle° 안 · range m 안 · 더 멂)이면 앞 적을 몰아침 — 빈틈 점수 + add ('press')
  shield: { angle: 20, range: 4.5, add: 0.5 },
  // 이끌기 (§3-8 — 6): 물러나는 동안 range m 안의 비어 있는 동료 쪽으로 옆 스틱 k × 물러나는 몫
  lure: { range: 4.5, k: 0.5 },
  // 역할 (사장님 11/18 결정 3 — 6 → 같은 편 AI 동료): 묶기 받은 몸은 그 상대 점수 − pin · 이어 치기 받은 몸은 − follow · 역할은 ttl(실제 초) 동안 (다시 주면 늘어남)
  role: { pin: 0.6, follow: 1.2, ttl: realS(1.5) },
  // 등 뒤 알림 (사장님 11/18 결정 7 — 사람 몸 · team_hud.js): 나를 겨눈 AI 가 공격 꼴로 칼끝 + engage 안 · 내 바라보는 쪽에서 deg° 넘게 뒤 → 그 몸의 화면 밖 화살표가 color 로 blink Hz 깜빡
  back: { deg: 90, blink: 4, color: '#ff3b2f' },
  // 수적 열세 (§3-5): 숙련도 레버(TEAM_FIGHT.lever 줄 세우기 · 피하기)의 몫 = base + (1 − base) × 층 몫 (숙련 0 ~ 2 = base · 5 · 6 = 1) · 내 동료와 붙은 적은 열세 셈에서 뺌
  out: { base: 0.3 },
};

// 서포트 — 유파마다 동료로서의 판단(셋 이상 판의 AI 만 · 판단 · 꼴만 · src/team_support.js) — 몫 = 아래 값 × 숙련 곡선 MINDSET.profF [사장님 11/19 · 11/20 · 값 확인 전]
