  maxTwist: 0.9, // 딛은 발에 대해 골반을 비틀 수 있는 최대 각도(라디안). 더 돌려면 발을 돌려 딛는다
  turnLead: 0.35, // 몸을 돌리는 중엔 이만큼(초) 앞질러 돌아갈 방향으로 발을 딛는다 // 뒷발 발끝을 바깥으로 트는 각도(라디안)
  guardHeight: 0.9, // 펜싱 자세 골반 높이(m): 무릎을 살짝 굽힌다
