  dsLowFast: 0.25, //  (bobUntil m/s에 가까워지면 이 배율까지 준다). 천천히 걸어도 골반이 2cm 넘게 출렁인다
  dsLowIn: 0.35, // 걷기 시작한 뒤 이 시간(초)에 걸쳐 dsLow를 0에서 다 켠다
