  sideDipFrom: 0.75, // 옆으로 가는 비율(0~1)이 이보다 클 때만 (비스듬히 걸을 땐 내리지 않는다)
  backDip: 0.015, // 뒷걸음에서 발을 디딜 때 골반을 살짝 내리는 깊이(m) (뒤로 가는 정도만큼)
  backFrom: 0.2, // 뒤로 가는 정도: 가려는 방향의 뒤쪽 몫(0~1)이 이보다 크면 늘기 시작해
  backFull: 0.5, //  이만큼 더 크면 다 찬다 (비스듬히 물러나는 것도 뒷걸음)
  backSideCut: 0.2, // 비스듬히 물러날 땐 옆으로 옮기는 보폭(sideStride)을 이 비율만큼 줄인다 (박자가 빨라진다)
  stanceKneeMax: 0.18, // 딛은 다리 무릎을 기본 굽힘보다 이 이상(라디안) 굽히지 않는다 (몸무게를 받을 때 무릎이 너무 꺾이지 않게). 0 = 끔
  runKneeCut: 0.5, // 뛰듯 빨리 갈 땐 그 한계를 이 비율만큼 줄인다
  loadTime: 0.2, // 디딘 뒤 무게를 받는 시간(초): 옆·뒷걸음 골반 내림(sideDip·backDip)과 무릎 굽힘 한계(stanceKneeMax ×1.5)가 이 창을 쓴다
  heelDead: 0.03, // 뒤꿈치를 이만큼(라디안)만 들면 닿을 땐 들지 않는다 (들락날락 떨지 않게)
  heelTD: 0.08, // 발이 이만큼(sin 기울기) 넘게 발끝으로 기운 채 디디면, 발끝 자리를 기준으로 딛은 자리를 잡는다
  heelBlend: 0.08, // 딛은 발이 엉덩이보다 이만큼(m) 뒤로 빠질 때까지 뒤꿈치 들기 몫을 조금씩 더한다 (골반 높이 목표)
  capRate: 0.5, // 골반 높이 목표가 다리가 닿는 높이보다 높을 때 내리는 최고 빠르기(m/s)
  heelMax: 0.5, // 뒤로 빠진 딛은 발의 뒤꿈치를 드는 최대 각도(라디안)
