  handMass: 1.5, // 되튐 계산에서 칼과 함께 밀리는 손·아래팔의 유효 질량(kg, 칼자루에 붙은 점 질량으로 본다)
  // 칼끼리 새로 부딪힌 순간 칼이 손 안에서 길이 축으로 도는 빠르기의 한도(rad/s, 부딪히기 전보다 빨라진 몫만).
  //  손아귀가 칼자루를 잡으니 코등이에 걸려 튕겨도 날이 휙 뒤집히지 않는다 (combat.js gripTwist)
