  // ① 칼끼리 쌍 반발 값(칼끼리 실제 튕김 — 칼마다 이 값의 제곱근을 걸어 곱이 이 값 · 콜라이더 제 값이 더 낮으면 그대로) [사장님 10/31 · 11/25 '실제 0.2로']
  restitution: 0.2,
  // 칼끼리 붙어 있는 동안(combat.js armSteel 과 같은 때) 칼 콜라이더 마찰 (오늘 0.4 늘). 닿은 날이 서로 물어 덜 미끄러진다 — 마른 쇠끼리 0.5~0.8, 날끼리 파고들어 물리면 그 위 [추정]
  friction: 1.2,
  // ② 닿은 뒤에도 미는 뜻 (ai.js): 치던 칼이 막히면 베기 길을 이 손 빠르기(m/s)로만 노리던 자리(길의 가운데 점 — 상대 빈틈)까지 밀고 거기서 멈춰 민다
  pressSpeed: 0.2,
