  holdMax: realS(1.5),
  // ②′ 성향에 따른 미는 정도 w = clamp(공격 성향 × 맞받기 성향 × 지금 감정, lo, hi) — 밀기 손 빠르기 · 버팀 상한 × w [사장님 10/31 · 셈 · 수 확인 전]
  will: { aggr0: 0.9, aggrK: 1.5, vor0: 0.4, vorK: 0.5, emoK: 0.5, lo: 0.5, hi: 1.5 },
