// 소리 (sound.js). 소리마다 들어보기: 메뉴의 "소리 들어보기"
export const SOUND = {
  volume: 0.8, // 전체 음량
  reverb: 0, // 경기장 울림 (0 = 끔. 전투는 마른 소리가 낫다는 피드백으로 끔). 쇳소리가 관중석에 되울리는 정도 (원래 소리 대비 울림 에너지 비율의 제곱근)
  samples: true, // 녹음된 소리(public/sfx, Kenney.nl CC0)를 합성 소리에 섞기
  maxVoices: 12, // 동시에 울리는 소리 개수 한도 (넘으면 가장 오래된 소리를 끈다 → 폰 부담 줄이기)
  // 타격 세기 눈금 (29차, 온몸 타격 R3 대비. sound.hitWeight): 'legacy' = 지금 소리 그대로, 'log' = hitKnee 위로 로그 무게를 켠다.
  // 디렉터가 R3 에서 'log' 로 넘긴다 (main.js 에서 sound.hitScale = 'log' 도 된다). hitKnee 까지는 두 눈금이 같은 소리다.
  hitScale: 'legacy',
  hitKnee: 200, // J. 이 위부터 무게가 붙는다 (지금 게임의 타격은 대체로 이 아래)
  hitHeavy: 500, // J. 무게 w 가 1 이 되는 에너지 (그 위는 로그로 천천히 더 오른다)
  // 큰 타격에 반응하는 배경 소리의 같은 소리 최소 간격(초 — 타격음은 안 걸림) [사장님 9/29]
  stageHitGap: 10,
  // 칼이 몸을 칠 때 소리 후보 'legacy' · 'synth' · 'rec' · 'samsho'(고르시기 전 'legacy') · 드루이드의 채찍 살 · 옷 맞음 소리('Whip Crack' 딱 부분 · src/whip_sound.js) [사장님 10/24]
  whipLashGain: 1, // C2 맞음 녹음 한 겹 음량 (event 음량은 칼 둔타와 같은 눈금 그대로 · 파일 최고 −1 dBFS 는 다른 채찍 녹음과 같음) — 확인표 2443 · 사장님 확인 전
  whipLashGap: 0.2, // s: C2 맞음 뒤 이 시간 안의 끝 '딱' · 다른 C2 맞음은 내지 않음 (한 맞음이 두 번 터지지 않게) — 확인표 2444 · 사장님 확인 전
  whipFlam: 0.06, // s: 끝 '딱' 뒤 이 시간 안의 C2 맞음은 내지 않음 (거의 같은 때 — 이미 난 '딱'이 대신) — 확인표 2444 · 사장님 확인 전
  // 비기 소리: 비기가 실제로 터진 순간 그 유파 녹음 한 번(사람 · AI 같음 · src/secret_sfx.js) [사장님 10/25]
  secretSfxGain: 1, // 이벤트 음량 (녹음 한 겹 · 파일 최고 −8 dBFS 받은 그대로 · 쇳소리 묶음 · 재생 빠르기 1) — 사장님 10/25 18:4x '음량 1.0으로 하고' (확인표 2543)
  // 파일마다 크기 맞춤(dB — 녹음 한 겹 음량으로만) [사장님 10/25 · 3.3 확인 전]
  secretSfxTrimDb: { 'secret/g1-clank': 0, 'secret/g2-dry': 3.3 },
  secretSfxFiles: { japanese: 'secret/g1-clank', italian: 'secret/g1-clank', chinese: 'secret/g1-clank', iberian: 'secret/g2-dry', german: 'secret/g2-dry' }, // 유파 → public/sfx 파일 (확장자 없음) — 사장님 10/25 결정 (확인표 2542)
};

/**
 * 타격감 (10/25 사장님 '타격감 보강도 진행해' — 감독 안 '맞는 순간의 힘에 비례해 화면 흔들림 · 아주 짧은 멈춤 · 묵직한 소리를 키움, 모든 무기에 같은 규칙, 대검이 가장 크게').
 *  셈 = src/impact_fx.js (순수 함수) · 쓰는 곳 = main.js onWound · onClash (멈칫 hitStop · 카메라 스프링 · sound.heft). 화면 · 소리만 — 판정 · 물리 · AI 는 그대로이고
 *  시뮬 도구는 main.js 를 돌리지 않아 AI 끼리 판도 그대로. · 흔들림 식, 무게 소리 없음). 값은 모두 사장님 확인 전 (확인표 2620 ~ 2629 ·
 *  기록 docs/strike/impact_feel_2026-10-25.md).
 */
export const IMPACT_FX = {
  // 타격 무게 H (J — 롱소드로 친 것과 같은 눈금) = 판정 에너지 × (때린 무기 무게 / massRef)^massExp.
  //  massExp 1 = 운동량(무게 × 빠르기) 눈금: 같은 에너지라도 무거운 칼이 더 묵직하다. 0 = 판정 에너지만 — 잰 값으로는 대검의 보통 맞음 에너지가 롱소드와 거의 같아(기록 §2) 대검이 더 크게 느껴지지 않는다
  massRef: 1.6, // kg — 롱소드 무게 (fighter.swordProps.m)
  massExp: 1, //
  // 세기 x (0 ~ 1) = ln(H / h0) / ln(h1 / h0): 에너지가 두 배가 될 때마다 같은 만큼 오른다 (눈 · 귀는 비율로 느낀다)
  h0: 15, // J — 이 아래는 0 (칼끝이 툭 스침 · 칼 면 가벼운 닿음)
  h1: 250, // J — 이 위는 1 (대검 큰 베기 · 비기 · 내려찍기 마무리)
  // 멈칫 (main.js hitStop — 화면 시간을 잠깐 0.12 배로 · 지금 멈칫과 같은 장치) = stop × x — 살을 깨끗이 가르고 지나가면 × passK, 박힘 · 뼈 · 투구 · 판금에 걸리면 × hardK, 위 끝은 지금 상한 0.1 s 그대로
  stop: 0.09, // s (짧은 효과 — 0.1 s 아래 제안 값)
  passK: 0.7,
  hardK: 1.15,
  stopMax: 0.1, // s — 멈칫 하나의 위 끝 (지금 상한 '최대 0.1초 — 조작이 늦게 느껴지지 않게' 그대로 · 새 값 아님)
  // 멈칫 묶음: 멈칫이 끝나고 chainGap 안에 다음 멈칫이 오면(한 칼이 팔 · 몸통을 잇달아 벰 · 맞음 뒤 곧장 부딪힘) 같은 묶음 — 한 묶음의 멈칫 합은 chainCap 까지만
  //  (멈칫이 거듭 이어 붙어 손이 굼떠지지 않게. 멈칫 = 화면 시간만 늦춤 — 물리 한 스텝 길이 · 스텝 차례는 그대로라 판정은 같다)
  chainCap: 0.1, // s — 지금 멈칫 상한과 같은 값
  chainGap: 0.2, // s — 시간 사다리 0.2 '반응'
  // 카메라 밀림 (main.js 카메라 스프링 — 지금 흔들림과 같은 장치) = 최대 × x^camPow · 방향 = 칼이 지나간 쪽 + 무거울수록 아래로(camDown × x — '쿵')
  camTaken: 2.2, // 내가 맞을 때 (지금 상한 1.6 × 1.4 = 2.24 와 같은 줄 — 내가 맞을 때가 더 크다)
  camDealt: 1.2, // 내가 칠 때 (지금 상한 1.6 × 0.8 = 1.28 과 같은 줄)
  camPow: 1.5, // 가벼운 타격은 더 부드럽게, 큰 타격만 크게
  camDown: 0.5,
  camCap: 2.4, // 타격 · 부딪힘이 겹쳐도 카메라 스프링 속도를 이 아래로 (폰 멀미 — 한 번 밀림 상한)
  camMaxOff: 0.09, // m — 카메라가 밀린 거리 벽 (맞음이 잇달아 와도 이 밖으로 안 감 · 한 번 밀림 위 끝 camCap 은 약 8.7 cm 라 닿지 않음 — main.js 스프링 적분 · impact_fx.js shakeWall)
  // 칼끼리 부딪힘 (main.js onClash — 지금 문턱 · 간격 그대로: 멈칫은 부딪힘 빠르기 6 m/s 넘을 때 · 0.5 s 에 한 번):
  //  부딪힌 에너지 = ½ μ vn² × STRIKE.energyScale (μ = 두 칼 무게의 환산 질량 m1 m2 / (m1 + m2) · vn = 맞닿는 방향 빠르기) × (2μ / massRef)^massExp → 같은 x 곡선
  clashStop: 0.8, // 멈칫 = stop × x × 이 값 (맞음보다 순하게)
  clashCam: 0.7, // 카메라 최대 (지금 상한 0.6 과 같은 줄)
  // 무게 소리 (sound.heft — 기존 타격음은 그대로 두고 낮고 둥근 '쿵' 한 겹만 더함): 음량 = gain × x^pow · 빠르기(음 높이) 1 → rate · 낮은 통과 lpLight → lpHeavy Hz
  sound: { gain: 0.9, pow: 2, rate: 0.6, lpLight: 3000, lpHeavy: 900, clash: 0.6 }, // clash = 칼끼리 부딪힘 음량 배율
  // 총알(권총 — gun.js 맞음 r.gun)은 무게 배율 없이 판정 에너지만 (총 무게는 맞은 몸에 실리지 않는다)
};

/**
 * 칼 잔상 띠 (외형 PM, 디렉터 R0 화면 신호 — src/sword_trail.js). 겉모습만: 물리·판정과 무관.
 *  최근 물리 자세 몇 개의 칼 선분(칼자루→칼끝)을 이어 만든 삼각형 띠. 빠를수록 짙고 잠깐 뒤에 사라진다.
 */
export const SWORD_TRAIL = {
  samples: 4, // 띠를 만들 최근 물리 자세 수 (2~4)
  life: 0.06, // 초(게임 시간): 자세 하나가 띠에서 사라지기까지
  vMin: 8, // m/s: 칼끝 속도가 이보다 느리면 안 보인다
  vMax: 25, // m/s: 이 속도에서 가장 짙다
  // 칼 궤적 v2: 보통 섞기 — 칼날 색을 어둡게 한 반투명 띠(칼보다 밝아지지 않음) [사장님 9/30]
  strength: 0.3, // 가장 짙을 때의 불투명도 (보통 섞기 — 0.3 이면 바탕이 70% 비친다)
  dim: 0.55, // 칼날 재질 색에 곱하는 밝기 (1 보다 작게 — 늘 칼보다 어둡다)
  hiltFade: 0.3, // 칼자루 쪽 불투명도 배율 (칼끝 줄기로 읽히게)
};

/**
 * 망토 흔들림 (10/24 — 사장님 '베르나르도 롤랑 아르토리아 망토에 다 넣어' · '스위치 필요 없어 바로 적용해' — src/cape_sway.js). 겉모습만: 물리 · 판정 · AI 와 무관.
 *  긴 망토 아래쪽이 몸통 움직임을 반 박자 늦게 따라오며 살짝 흔들린다(뼈 몇 개 스키닝 — 천 시뮬레이션 아님). 값은 모두 사장님 확인 전(확인표 2341 ~ 2343).
 *  각은 아랫단 기준(rad) — 위로 갈수록 (높이 몫)^ramp 만큼 작아져 어깨에서 0.
 */
const DEG = Math.PI / 180;
export const CAPE = {
  bones: 4, // 움직이는 줄 뼈 수 (어깨 줄 고정 뼈 하나는 따로)
  ramp: 1.5, // 줄 뼈 k 의 흔들림 몫 = (k / bones)^ramp — 어깨 0 → 아랫단 1
  lag: 0.2, // s — 시간 사다리 '반응': 몸통 속도를 이만큼 늦게 따라간 값과의 차 = 반 박자 늦은 가속
  settle: 0.6, // s — 시간 사다리 '이어짐': 흔들림이 5 % 안으로 가라앉는 시간 (스프링 고유 진동수 = 3 / (damping · settle))
  damping: 0.5, // 감쇠비 — 한 번 살짝 되넘고 멎는다
  accel: 0.05, // rad / (m/s²) — 몸통 가속에 아랫단이 뒤로 처지는 몫
  turn: 0.04, // rad / (rad/s) — 몸통이 앞뒤 · 옆으로 기울어 도는 빠르기에 아랫단이 뒤에 남는 몫
  twist: 0.025, // rad / (rad/s) — 몸통이 제자리에서 도는(비트는) 빠르기에 아랫단이 뒤에 남는 몫
  clamp: { fwd: 3 * DEG, back: 12 * DEG, side: 7 * DEG, twist: 7 * DEG }, // 아랫단 각 묶음 (부드럽게 — c · tanh(각 / c)): 앞(다리 쪽)은 작게
  idle: { amp: 0.5 * DEG, period: 3.0 }, // 숨쉬기 흔들림 (앞뒤 · 옆은 반 크기에 주기 × 1.5) — 주기 3.0 s = 사다리 '무장' 1.5 × 2
};

/**
 * 칼 팔 관절 가동 범위 교정 (사장님 10/9 '관절이 구체인형처럼 덜렁거린다·해부학 범위를 벗어난다·칠 때 팔을 살짝 굽힌다' — 10/9 'anat' 묶음 늘 켬 · 11/17 묶음 스위치 걷음).
 *  기록·측정: docs/motion/joint_range_2026-10-09.md · 계기 tools/sim/joint_range.mjs. 새 값은 모두 사장님 확인 전 (확인표 290~).
 *  늘: ⓑ 범위 끝 되돌림 스프링(위팔 돌림·손목 끝 — 팔꿈치 몫 끔) · 플레이어 칼만 ⓒ 손 목표 자르기(playerReachFrac) · 위팔 비틀기 서보 twistK (사장님 10/9 18:4x '좋습니다' · 18:5x '기본에 넣어').
 *   ⓐ 엔진 한도 · 모든 칼 ⓒ 판은 들이지 않아 지웠다
 *  각은 도. 해부학 출처: AAOS "Joint Motion: Method of Measuring and Recording"(1965) · Norkin & White "Measurement of Joint Motion" · Soucie 외 2011 (Haemophilia 17:500)
 */
export const JOINTS = {
  // 팔꿈치 돌림: 칼이 앞 · 아래를 겨눠 새끼 쪽으로 꺾이면 같은 손 자리에서 팔꿈치만 돌려 척측 한도 안으로(사람 · AI 모든 칼 팔) [사장님 10/24]
  elbowSwivel: 1,
  swivelThrust: 1, // 탭 찌르기 동안 팔꿈치가 손목 한도 밖이면 칼이 아래팔 연장에 가장 가까운 돌림 [확인 전]
  wristPronate: 1, // 한손 무기 엎친 손 길: 손목이 사람 범위 안이 되는 손 면을 쉬는 칼 면 목표로(베는 토막 빼고) [사장님 10/25 · 확인 전]
  cutPronate: 1, // 엎친 손 길은 자세에 쉬는 동안만(움직이는 동안은 swivelHuman + 손 면 교정) [사장님 10/25 · 확인 전]
  swivelHuman: 1, // 한손 무기 팔꿈치 돌림이 사람 팔 범위를 지킴(한도 밖 돌림은 안 함) [사장님 10/25 · 확인 전]
  swivelTau: 0.2, // 팔꿈치 돌림 따라감 시간 · 0 = 곧장 [확인 전]
  // 비정상 손목 교정: 칼 겨눔이 아래팔과 이루는 손 면 안 각이 사람 범위 밖이면 칼끝만 범위 끝까지(사람 · AI 모든 칼 팔) [사장님 10/24]
  wristGuard: 1,
  twist: [-70, 90], // 위팔 돌림 [안쪽, 바깥쪽] (AAOS 안쪽 70 · 바깥쪽 90). 기준 = 팔을 앞으로 뻗고 팔꿈치 경첩 축이 옆(아래팔이 위로 접힘)
  wristFE: 70, // 손목 굽힘·폄 (칼날이 아래팔 경첩 면 밖으로 나가는 각) 한쪽 (AAOS 굽힘 80 · 폄 70). 어깨 폄 60 은 48 판 최대 45° 라 한도를 더하지 않았다
  // ⓑ 끝 스프링: 범위 끝 zone 도 앞부터 되돌림 (가운데는 힘 0 → 휘두르는 속도에 손대지 않음)
  zone: 15,
  // 팔꿈치 몫: 이 굽힘 아래로 펴지면 되돌림 (도). 0 = 끔(권고). 15 로 재니 플레이어 베기 맞음 E 가 110·101 → 97·91 J 로 줄었다
  //  (곧은 팔이 칼 뒤에 싣는 유효 질량을 굽힘이 덜어 낸다 — 기록 §5). 쭉 뻗음은 ⓒ(명령을 바꿈)로 다룬다
  elbowSoft: 0,
  kElbow: 60, // N·m/rad
  kTwist: 30, // N·m/rad (위팔 돌림. 비틀기 축 관성이 작아 안정 한계 안)
  dTwist: 0.3, // N·m·s/rad
  kWrist: 20, // N·m/rad (손목 굽힘·폄 끝, 칼 ↔ 아래팔)
  dWrist: 0.4, // N·m·s/rad
  // 플레이어 칼만 ⓒ: 사람 손가락이 모는 칼의 손 목표를 어깨에서 (위팔 + 아래팔) × 이 값 안으로 (0.975 ≈ 팔꿈치 최소 25° 굽힘·리치 −1.4 cm). AI 는 1 그대로 (확인표 320)
  playerReachFrac: 0.975,
  // 위팔 비틀기 서보 강성 (N·m/rad — 전 25). 감쇠 0.8·상한 20 N·m 도 같은 배율 (fighter.js manualMuscle, 확인표 321)
  twistK: 60,
  // 한손 칼끝 고침('fix' — 세이버 표 감는 자리 칼끝을 분명히 위 · 아래로 + 옆 패드 칼끝 접기) [10/10]
  oneTipAz: [26, 46], // 접기를 섞기 시작 → 다 거는 방위 |az| (°, 손 매핑 guardDir: 패드 x 0.32 → 0.52) — 그 안쪽은 상대를 겨누는 자리라 그대로
  oneTipFold: -14, // 가르는 올림각 (°): 이 위면 위로, 아래면 아래로 접는다 (±5° 는 섞음 — 패드 y −0.12 쯤)
  oneTipUp: 55, // 위로 접을 때 올림각 하한 (°) — 마이어 1570 두삭 Wacht·Entrüst 처럼 칼끝이 분명히 위
  oneTipDown: -45, // 아래로 접을 때 올림각 상한 (°) — 두삭 Eber·Nebenhut 처럼 칼끝이 분명히 아래
  // 플레이어 칼 날 세우기(사람 손가락 칼만): 거른 손 목표가 따라갈 몫을 날 방향에 더함 [사장님 10/10 · 값 감독]
  playerEdgeLead: 1, // 입력 미리 돌리기 무게: 예측한 칼날 70 % 지점 속도 × 이 값을 지금 속도에 더한다
};

// ── 상점(대기실 '상점' 칸 · src/shop_rules.js · shop_panel.js · 대사 shop_text.js — 싸움 · 시뮬은 안 읽음): 물건 등급 · 값 · 뿔피리 · 4 시간 갱신 · 얼터 5 % [사장님 10/30 · 10/31 · 나머지 감독 기본]
