  // 한 번에 파는 물건 수(2 또는 3) · 옛 저장 2 칸은 셋으로 채움 [사장님 10/31 · 3 확인 전]
  items: 3, // 사장님 10/31 08:xx '상점 3개 좋아' 결정 (확인표 3073)
  // 보통 상인 등급 확률 (무게 — 합 100) · 사장님 10/30 19:0x 결정 ('??? 등급을 제외하고 커먼 60% 레어 25% 에픽 10% 레전드 5%') — 쓰레기 · ??? 는 없음
  tierWeights: { common: 60, rare: 25, epic: 10, legend: 5 },
  // 값 [아래, 위] (양 끝 포함) · 사장님 10/30 19:0x 결정 — 금화(coins) · 뿔피리(horns)
  price: {
    common: { coins: [800, 1000] },
    rare: { coins: [1600, 2000] },
    epic: { coins: [3300, 3900], horns: [2, 4] },
    legend: { coins: [5000, 5800], horns: [3, 7] },
  },
  coinStep: 10, // 금화 값 눈금 (10 = 10 단위 · 1 = 아무 정수) · 사장님 10/31 01:3x 결정 ('금화 10단위 ok')
  refreshHours: 4, // 갱신 간격 (현실 시간 · 시) · 사장님 10/30 19:0x 결정 ('현실 시간으로 4시간마다 갱신')
  slotTzHours: 9, slotStartHour: 0, // 갱신 시각 맞춤: 한국 시간(UTC+9) 0 시부터 4 시간마다 = 00 · 04 · 08 · 12 · 16 · 20 시 (기기 시간대와 상관없이) · 사장님 10/31 01:3x 결정 ('갱신시간 ok')
  alterChance: 0.05, // 갱신마다 얼터 인격(광기의 쥘리아 크리스테바)으로 나올 확률 · 사장님 10/30 19:0x 결정 ('갱신될 때마다 5% 확률로 얼터 인격')
  alterTiers: ['trash', 'mystery'], // 얼터가 파는 등급 — 같은 확률(물건마다 반반) · 사장님 10/30 19:0x 결정 ('무조건 쓰레기 등급과 ??? 등급의 아이템만을 동일한 확률로')
  alterPrice: { heads: 3 }, // 얼터 값 = 머리(목) 3 · 금화 없음 · 사장님 10/30 19:0x 결정 ('판매가격은 일괄 목 3개')
  keeper: 'julia', alterKeeper: 'julia_mad', // 상인 그림 id (public/ui/portraits/<id>.webp — 따로 들여오는 그림 · 없으면 빈 액자 1)
  // 뿔피리 (새 재화 — lobby_progress.js horns): 왕을 이긴 판에서 hornChance 로 +hornAmount · 여정 · 방랑(내 저장 판)만 — 테스트 경로 · 주소 고정 판은 없음
  hornChance: 0.5, // 사장님 10/30 19:0x 결정 ("뿔피리는 '왕'을 잡으면 50% 확률로 얻어")
