  testMode: VITE_ENV.VITE_SAENGSA_TEST === '1', // 시험판: 신청 창 늘 열림 · 모든 경기 바로(쉬는 시간 · 대진 시각 · 기권 없음 — 상대끼리 경기는 앞 대진이 다 끝나면) · 대회가 끝나면 '다음 대회'
