  signupTo: 2, // 신청 끝 시 (새벽 2시 — 대회 날). signupFrom > signupTo 면 시작은 대회 전날 · 사장님 10/29 14:1x 결정 · 11/12 같은 수
  // 바로 시작: 신청하면 첫 경기를 곧바로 · 내 경기가 끝나면 다음도 곧바로 · 상대끼리는 앞 대진이 끝나면 · 시각을 안 보임 · false = 옛 시각 규칙 [사장님 11/12]
  instant: true,
  startHour: 10, // 첫 대진 시각 (아침 10시) · 사장님 10/29 14:1x 결정 — instant false 일 때만
