  restH: 2, // 결과를 저장한 뒤 그 팀의 다음 경기를 시작할 수 있을 때까지 (시간) · 내 팀은 사장님 10/29 14:1x 결정 · 상대 팀도 같은 규칙인 것은 확인 전 — instant false 일 때만
  // 기권: 내 경기를 다음 신청 창(밤 10시)까지 하지 않으면 기권(saengsa_rules.js deadlineOf) [사장님 10/29]
  teams: 16, // 대진표 팀 수 (2 의 거듭제곱 — 16 = 16강 · 8강 · 4강 · 결승) · 사장님 10/29 14:5x 결정 '16팀으로 해' (이름난 인물은 한 대회에 한 번씩 · 남는 자리는 무명 검객 — 15:5x · 아래 nameless)
  teamSize: 3, // 한 팀 = 나 + 동료 둘 · 사장님 10/29 14:2x 결정
