  assignUnique: true, // 한 무기는 한 사람에게만(가진 것이 한 자루씩이라 — 살아 있는 사람끼리) · 사장님 확인 전
  entry: { title: 'conqueror', weapons: 5 }, // 입장(신청) 조건: 호칭 정복자(title_rules.js — 방랑 10연승 TITLE.conquerWins) + 가진 무기 5 개 이상 · 사장님 10/29 18:2x 결정 · 못 채우면 '생사전 입장'은 꺼지고 대진표 보기만
