  aiArm: { prof: 1, tier: { trash: -1, common: 0, rare: 0.4, epic: 0.8, legend: 1.2, mystery: 0.8 }, sig: 3, zero: 10, broken: 3 }, // broken = 부러진 무기 감점(몸 상태를 곱한 몫에서 — 그래도 줄 수는 있음)
